//! Writes the model as Rust source for `crates/idml/src/model/`.
//!
//! Generated types implement the runtime's `Content` trait: `placeholder`
//! (a value to read into, never observable), `read_into` (fill a value in
//! place) and `write`. Reading in place keeps the recursive readers' stack
//! frames independent of the size of the structs they read.

use std::collections::BTreeMap;
use std::fmt::Write as _;

use crate::model::*;
use crate::names::camel;

/// Generated files by name (`mod.rs`, `spread.rs`, …).
pub fn rust(model: &Model) -> Result<BTreeMap<String, String>, String> {
    let roots: BTreeMap<TypeId, &Root> = model.roots.iter().map(|r| (r.ty, r)).collect();
    let mut modules: BTreeMap<&str, Vec<TypeId>> = BTreeMap::new();
    for (id, t) in model.types.iter().enumerate() {
        modules.entry(&t.module).or_default().push(id);
    }
    let mut files = BTreeMap::new();
    for (module, mut ids) in modules {
        ids.sort_by(|a, b| model.types[*a].name.cmp(&model.types[*b].name));
        let mut out = String::new();
        out.push_str(HEADER);
        out.push_str(
            "#![allow(unused_imports)]\n\nuse super::*;\nuse crate::value::{ranged, value_enum, value_union};\n\
             use crate::xml::{Content, Reader, Writer};\n\
             use crate::{DateTime, Error, Parsed, Part, PartFile, PartPath, ReadOptions, Token};\n",
        );
        for id in ids {
            out.push('\n');
            Emitter { model, out: &mut out }.ty(id, roots.get(&id).copied())?;
        }
        files.insert(format!("{module}.rs"), out);
    }
    let mut m = String::new();
    m.push_str(HEADER);
    let _ = write!(
        m,
        "//! The IDML document model, generated from the InDesign {} package schemas.\n\
         //!\n\
         //! `schema-map.tsv` next to the crate's `Cargo.toml` lists the schema item behind\n\
         //! every type, field and variant.\n\n\
         #![allow(clippy::large_enum_variant, clippy::too_many_arguments, clippy::new_without_default)]\n\n",
        model.indesign_version
    );
    let names: Vec<String> = files.keys().map(|f| f.trim_end_matches(".rs").to_owned()).collect();
    for n in &names {
        let _ = writeln!(m, "mod {n};");
    }
    m.push_str("pub(crate) mod upgrades;\n");
    m.push('\n');
    for n in &names {
        let _ = writeln!(m, "pub use {n}::*;");
    }
    let _ = write!(
        m,
        "\n/// The `DOMVersion` this model reads and writes.\npub const DOM_VERSION: &str = {:?};\n\n\
         /// The InDesign build that generated the schemas.\npub const INDESIGN_VERSION: &str = {:?};\n\n\
         /// SHA-256 over the schema files (path and SHA-256 of each) the model was generated from.\n\
         pub const SCHEMA_SHA256: &str = {:?};\n",
        model.dom_version, model.indesign_version, model.sha256
    );
    files.insert("mod.rs".to_owned(), m);
    Ok(files)
}

/// The Rust variant for each enumeration literal.
pub fn enum_variants(literals: &[Literal]) -> Vec<String> {
    let mut used: Vec<String> = Vec::new();
    for lit in literals {
        let mut v = camel(&lit.value);
        while used.contains(&v) {
            v.push('_');
        }
        used.push(v);
    }
    used
}

pub fn type_name(model: &Model, id: TypeId) -> &str {
    &model.types[id].name
}

pub const HEADER: &str = "// @generated by idml-codegen from the InDesign IDML schemas. Do not edit.\n\n";

/// A field of a generated struct.
struct Field {
    name: String,
    ty: String,
    /// The value `new` gives it; `None` for a `new` parameter.
    default: Option<String>,
    placeholder: String,
}

struct Emitter<'m, 'o> {
    model: &'m Model,
    out: &'o mut String,
}

impl Emitter<'_, '_> {
    fn name(&self, id: TypeId) -> &str {
        &self.model.types[id].name
    }

    fn line(&mut self, indent: usize, text: &str) {
        for _ in 0..indent {
            self.out.push_str("    ");
        }
        self.out.push_str(text);
        self.out.push('\n');
    }

    fn doc(&mut self, indent: usize, lines: &[String]) {
        for l in lines {
            if l.is_empty() {
                self.line(indent, "///");
            } else {
                self.line(indent, &format!("/// {l}"));
            }
        }
    }

    fn ty(&mut self, id: TypeId, root: Option<&Root>) -> Result<(), String> {
        let t = &self.model.types[id];
        let mut doc: Vec<String> = Vec::new();
        if let Some(e) = &t.element {
            doc.push(format!("The `<{e}>` element."));
            doc.push(String::new());
        }
        if !t.doc.is_empty() {
            doc.extend(t.doc.iter().map(|l| escape_doc(l)));
            doc.push(String::new());
        }
        let files: Vec<String> = t.files.iter().map(|f| format!("`{f}`")).collect();
        let files = if files.is_empty() { String::new() } else { format!(" in {}", files.join(", ")) };
        doc.push(format!("Schema: `{}`{files}.", escape_code(&t.origin)));
        if let Some(since) = &t.trace.since {
            doc.push(String::new());
            doc.push(since.clone());
        }
        match &t.kind {
            TypeKind::Enum(literals) => {
                self.line(0, "value_enum! {");
                self.doc(1, &doc);
                self.line(1, &format!("{} {{", t.name));
                for (lit, v) in literals.iter().zip(enum_variants(literals)) {
                    if let Some(since) = &lit.trace.since {
                        self.line(2, &format!("/// {since}"));
                    }
                    self.line(2, &format!("{v} = {:?},", lit.value));
                }
                self.line(1, "}");
                self.line(0, "}");
            }
            TypeKind::Ranged { base, min, max } => {
                let (ty, extra) = match base {
                    Scalar::Double => ("f64", ""),
                    Scalar::Int => ("i32", ", Eq, Hash, Ord"),
                    Scalar::Short => ("i16", ", Eq, Hash, Ord"),
                };
                let lit = |s: &str| if *base == Scalar::Double && !s.contains(['.', 'e', 'E']) { format!("{s}.0") } else { s.to_owned() };
                self.line(0, "ranged! {");
                self.doc(1, &doc);
                self.line(1, &format!("{}: {ty} = {} ..= {}{extra}", t.name, lit(min), lit(max)));
                self.line(0, "}");
            }
            TypeKind::Union(members) => {
                self.line(0, "value_union! {");
                self.doc(1, &doc);
                self.line(1, &format!("{} {{", t.name));
                for m in members {
                    self.line(2, &format!("{},", self.name(*m)));
                }
                self.line(1, "}");
                self.line(0, "}");
            }
            TypeKind::Alias(v) => {
                self.doc(0, &doc);
                self.line(0, &format!("pub type {} = {};", t.name, self.value_rust(v)));
            }
            TypeKind::Struct(c) => self.structure(&t.name, &doc, c, root)?,
            TypeKind::Choice(vs) => self.choice(&t.name, &doc, vs)?,
            TypeKind::Children(ms) => self.children(&t.name, &doc, ms)?,
        }
        Ok(())
    }

    // -- Rust types ----------------------------------------------------------------

    fn value_rust(&self, v: &ValueType) -> String {
        match v {
            ValueType::String => "String".to_owned(),
            ValueType::Bool => "bool".to_owned(),
            ValueType::Int => "i32".to_owned(),
            ValueType::Short => "i16".to_owned(),
            ValueType::Double => "f64".to_owned(),
            ValueType::DateTime => "DateTime".to_owned(),
            ValueType::Token => "Token".to_owned(),
            ValueType::PartPath => "PartPath".to_owned(),
            ValueType::Named(id) => self.name(*id).to_owned(),
            ValueType::Array(v, n) => format!("[{}; {n}]", self.value_rust(v)),
            ValueType::List(v) => format!("Vec<{}>", self.value_rust(v)),
        }
    }

    fn ty_rust(&self, ty: &Ty) -> String {
        match ty {
            Ty::Unit => "()".to_owned(),
            Ty::Value(v) => self.value_rust(v),
            Ty::Named(id) => self.name(*id).to_owned(),
            Ty::Vec(e) => format!("Vec<{}>", self.elem_rust(e)),
            Ty::Array(e, n) => format!("[{}; {n}]", self.elem_rust(e)),
            Ty::Wrap(e) => self.elem_rust(e),
        }
    }

    fn elem_rust(&self, e: &Elem) -> String {
        match e.part {
            Some(PartRef::Path) => format!("Part<{}>", self.ty_rust(&e.ty)),
            _ => self.ty_rust(&e.ty),
        }
    }

    fn boxed(t: String, boxed: bool) -> String {
        if boxed { format!("Box<{t}>") } else { t }
    }

    fn field_rust(&self, f: &ElemField) -> String {
        let t = Self::boxed(self.elem_rust(&f.elem), f.boxed);
        match f.occurs {
            Occurs::One => t,
            Occurs::Optional => format!("Option<{t}>"),
            Occurs::Many => format!("Vec<{t}>"),
        }
    }

    // -- placeholders ----------------------------------------------------------------

    fn value_placeholder(&self, v: &ValueType) -> String {
        match v {
            ValueType::String => "String::new()".to_owned(),
            ValueType::Bool => "false".to_owned(),
            ValueType::Int | ValueType::Short => "0".to_owned(),
            ValueType::Double => "0.0".to_owned(),
            ValueType::DateTime => "DateTime::placeholder()".to_owned(),
            ValueType::Token => "Token::placeholder()".to_owned(),
            ValueType::PartPath => "PartPath::placeholder()".to_owned(),
            ValueType::Named(id) => {
                let t = &self.model.types[*id];
                match &t.kind {
                    TypeKind::Enum(literals) => {
                        format!("{}::{}", t.name, enum_variants(literals).first().map_or("", String::as_str))
                    }
                    TypeKind::Ranged { .. } => format!("{}::PLACEHOLDER", t.name),
                    TypeKind::Union(members) => match members.first() {
                        Some(m) => format!("{}::{}({})", t.name, self.name(*m), self.value_placeholder(&ValueType::Named(*m))),
                        None => String::new(),
                    },
                    TypeKind::Alias(v) => self.value_placeholder(v),
                    _ => format!("{}::placeholder()", t.name),
                }
            }
            ValueType::Array(v, _) => format!("std::array::from_fn(|_| {})", self.value_placeholder(v)),
            ValueType::List(_) => "Vec::new()".to_owned(),
        }
    }

    fn ty_placeholder(&self, ty: &Ty) -> String {
        match ty {
            Ty::Unit => "()".to_owned(),
            Ty::Value(v) => self.value_placeholder(v),
            Ty::Named(id) => format!("{}::placeholder()", self.name(*id)),
            Ty::Vec(_) => "Vec::new()".to_owned(),
            Ty::Array(e, _) => format!("std::array::from_fn(|_| {})", self.elem_placeholder(e)),
            Ty::Wrap(e) => self.elem_placeholder(e),
        }
    }

    fn elem_placeholder(&self, e: &Elem) -> String {
        match e.part {
            Some(PartRef::Path) => format!("Part::new(PartPath::placeholder(), {})", self.ty_placeholder(&e.ty)),
            _ => self.ty_placeholder(&e.ty),
        }
    }

    // -- reading -------------------------------------------------------------------

    /// True when `e` is read in place (`Content::read_into`): an element
    /// whose content is a generated type, with no literal attributes of its
    /// own and not a part reference.
    fn in_place(e: &Elem) -> bool {
        e.part.is_none() && e.fixed.is_empty() && matches!(e.ty, Ty::Named(_))
    }

    /// An expression of type `Result<T, Error>` reading `ty` from reader `r`.
    fn ty_read(&self, ty: &Ty) -> String {
        match ty {
            Ty::Unit => "Ok(())".to_owned(),
            Ty::Value(_) => "r.text()".to_owned(),
            Ty::Named(id) => format!("{}::read(r)", self.name(*id)),
            Ty::Vec(e) => format!("r.elems({:?}, {})", e.name, self.read_fn(e)),
            Ty::Array(e, _) => format!("r.array({:?}, {})", e.name, self.read_fn(e)),
            Ty::Wrap(e) => format!("r.elem({:?}, {})", e.name, self.read_fn(e)),
        }
    }

    /// A function reading the content of element `e` and returning it.
    fn read_fn(&self, e: &Elem) -> String {
        match (&e.part, &e.ty) {
            (Some(PartRef::Path), Ty::Named(id)) => return format!("|r| r.part::<{}>()", self.name(*id)),
            (Some(PartRef::Fixed(src)), Ty::Named(id)) => return format!("|r| r.fixed_part::<{}>({src:?})", self.name(*id)),
            (None, Ty::Named(id)) if e.fixed.is_empty() => return format!("{}::read", self.name(*id)),
            _ => {}
        }
        let mut body: Vec<String> = e.fixed.iter().map(|f| format!("r.fixed({:?}, {:?}, {})?;", f.name, f.value, f.token)).collect();
        body.push(self.ty_read(&e.ty));
        let param = if e.fixed.is_empty() && e.ty == Ty::Unit { "_" } else { "r" };
        if body.len() == 1 { format!("|{param}| {}", body.join(" ")) } else { format!("|{param}| {{ {} }}", body.join(" ")) }
    }

    /// Statements reading a sequence field into `v`.
    fn read_field(&self, f: &ElemField) -> String {
        let (field, name) = (&f.field, &f.elem.name);
        if Self::in_place(&f.elem) {
            return match (f.occurs, f.boxed) {
                (Occurs::One, false) => format!("r.elem_into({name:?}, &mut v.{field})?;"),
                (Occurs::One, true) => format!("v.{field} = r.boxed({name:?})?;"),
                (Occurs::Optional, false) => format!("r.opt_elem_into({name:?}, &mut v.{field})?;"),
                (Occurs::Optional, true) => format!("if r.peek() == Some({name:?}) {{ v.{field} = Some(r.boxed({name:?})?); }}"),
                (Occurs::Many, _) => format!("r.elems_into({name:?}, &mut v.{field})?;"),
            };
        }
        let read = self.read_fn(&f.elem);
        let read = if f.boxed { format!("|r| ({read})(r).map(Box::new)") } else { read };
        let call = match f.occurs {
            Occurs::One => "elem",
            Occurs::Optional => "opt_elem",
            Occurs::Many => "elems",
        };
        format!("v.{field} = r.{call}({name:?}, {read})?;")
    }

    // -- writing -------------------------------------------------------------------

    /// An expression of type `Result<(), Error>` writing `ty` from the
    /// reference `v` with writer `w`.
    fn ty_write(&self, ty: &Ty, v: &str, depth: usize) -> String {
        match ty {
            Ty::Unit => "Ok(())".to_owned(),
            Ty::Value(_) => format!("w.text({v})"),
            Ty::Named(_) => format!("{v}.write(w)"),
            Ty::Vec(e) | Ty::Array(e, _) => {
                let x = format!("x{depth}");
                format!("{v}.iter().try_for_each(|{x}| {})", self.write_elem(e, &x, depth + 1))
            }
            Ty::Wrap(e) => self.write_elem(e, v, depth + 1),
        }
    }

    /// An expression of type `Result<(), Error>` writing element `e` with
    /// content `v`.
    fn write_elem(&self, e: &Elem, v: &str, depth: usize) -> String {
        match &e.part {
            Some(PartRef::Path) => return format!("w.part({:?}, {v}.src.as_str(), &{v}.content)", e.name),
            Some(PartRef::Fixed(src)) => return format!("w.part({:?}, {src:?}, {v})", e.name),
            None => {}
        }
        let mut body: Vec<String> = e.fixed.iter().map(|f| format!("w.fixed({:?}, {:?})?;", f.name, f.value)).collect();
        body.push(self.ty_write(&e.ty, v, depth));
        let param = if e.fixed.is_empty() && e.ty == Ty::Unit { "_" } else { "w" };
        let body = if body.len() == 1 { body.join(" ") } else { format!("{{ {} }}", body.join(" ")) };
        format!("w.elem({:?}, |{param}| {body})", e.name)
    }

    fn write_field(&self, f: &ElemField) -> String {
        match f.occurs {
            Occurs::One if f.elem.ty == Ty::Unit => format!("{}?;", self.write_elem(&f.elem, "v", 0)),
            Occurs::One => {
                let source = if f.boxed { format!("self.{}.as_ref()", f.field) } else { format!("&self.{}", f.field) };
                format!("let v = {source}; {}?;", self.write_elem(&f.elem, "v", 0))
            }
            Occurs::Optional => {
                let source = if f.boxed { format!("self.{}.as_deref()", f.field) } else { format!("&self.{}", f.field) };
                format!("if let Some(v) = {source} {{ {}?; }}", self.write_elem(&f.elem, "v", 0))
            }
            Occurs::Many => format!("for v in &self.{} {{ {}?; }}", f.field, self.write_elem(&f.elem, "v", 0)),
        }
    }

    // -- structs -------------------------------------------------------------------

    fn struct_fields(&mut self, c: &Content, emit: bool) -> Result<Vec<Field>, String> {
        let mut fields: Vec<Field> = Vec::new();
        for a in &c.attrs {
            let t = self.value_rust(&a.ty);
            let (ty, default) = if a.required { (t, None) } else { (format!("Option<{t}>"), Some("None".to_owned())) };
            if emit {
                self.line(1, &format!("/// `@{}`: `{}`.{}", a.name, escape_code(&a.schema), since(&a.trace)));
                self.line(1, &format!("pub {}: {ty},", a.field));
            }
            let placeholder = if a.required { self.value_placeholder(&a.ty) } else { "None".to_owned() };
            fields.push(Field { name: a.field.clone(), ty, default, placeholder });
        }
        match &c.body {
            Body::Empty => {}
            Body::Text { field, ty, schema, trace } => {
                let t = self.value_rust(ty);
                if emit {
                    self.line(1, &format!("/// Text content: `{}`.{}", escape_code(schema), since(trace)));
                    self.line(1, &format!("pub {field}: {t},"));
                }
                fields.push(Field { name: field.clone(), ty: t, default: None, placeholder: self.value_placeholder(ty) });
            }
            Body::Children(items) => {
                for item in items {
                    let (slots, interleaved) = match item {
                        Item::Elem(f) => (vec![Slot::Elem(f.clone())], false),
                        Item::Interleave(slots) => (slots.clone(), true),
                    };
                    for s in &slots {
                        match s {
                            Slot::Elem(f) => {
                                let ty = self.field_rust(f);
                                if emit {
                                    match &f.elem.part {
                                        Some(_) => self.line(1, &format!("/// The part referenced by `<{} src>`.{}", f.elem.name, since(&f.trace))),
                                        None => self.line(1, &format!("/// `<{}>`.{}", f.elem.name, since(&f.trace))),
                                    }
                                    if interleaved {
                                        self.line(1, "///");
                                        self.line(1, "/// In any order with its siblings in the schema's interleave.");
                                    }
                                    self.line(1, &format!("pub {}: {ty},", f.field));
                                }
                                let (default, placeholder) = match (f.occurs, &f.elem.ty) {
                                    (Occurs::Optional, _) => (Some("None".to_owned()), "None".to_owned()),
                                    (Occurs::Many, _) | (Occurs::One, Ty::Vec(_)) => (Some("Vec::new()".to_owned()), "Vec::new()".to_owned()),
                                    (Occurs::One, Ty::Unit) => (Some("()".to_owned()), "()".to_owned()),
                                    (Occurs::One, _) => {
                                        let p = self.elem_placeholder(&f.elem);
                                        (None, if f.boxed { format!("Box::new({p})") } else { p })
                                    }
                                };
                                fields.push(Field { name: f.field.clone(), ty, default, placeholder });
                            }
                            Slot::Group { field, ty } => {
                                let TypeKind::Children(ms) = &self.model.types[*ty].kind else {
                                    return Err("group is not a children type".to_owned());
                                };
                                let names: Vec<String> = ms.iter().map(|m| format!("`<{}>`", m.elem.name)).collect();
                                let t = format!("Vec<{}>", self.name(*ty));
                                if emit {
                                    self.line(1, &format!("/// {} in document order", names.join(", ")));
                                    self.line(1, &format!("pub {field}: {t},"));
                                }
                                fields.push(Field {
                                    name: field.clone(),
                                    ty: t,
                                    default: Some("Vec::new()".to_owned()),
                                    placeholder: "Vec::new()".to_owned(),
                                });
                            }
                        }
                    }
                }
            }
        }
        Ok(fields)
    }

    fn structure(&mut self, name: &str, doc: &[String], c: &Content, root: Option<&Root>) -> Result<(), String> {
        let required = c.has_required();
        self.doc(0, doc);
        self.line(0, if required { "#[derive(Debug, Clone, PartialEq)]" } else { "#[derive(Debug, Clone, Default, PartialEq)]" });
        self.line(0, &format!("pub struct {name} {{"));
        let fields = self.struct_fields(c, true)?;
        self.line(0, "}");

        // Attributes are read and written by functions of their own when the
        // element also has children, so that the frames of the functions that
        // recurse through the children stay small.
        let split = matches!(c.body, Body::Children(_)) && !c.attrs.is_empty();
        if required || split {
            self.out.push('\n');
            self.line(0, &format!("impl {name} {{"));
            if required {
                self.line(1, "/// A value with the required data; everything optional is absent.");
                let params: Vec<String> = fields
                    .iter()
                    .filter(|f| f.default.is_none())
                    .map(|f| {
                        let t = f.ty.strip_prefix("Box<").and_then(|t| t.strip_suffix('>')).unwrap_or(&f.ty);
                        if t == "String" { format!("{}: impl Into<String>", f.name) } else { format!("{}: {t}", f.name) }
                    })
                    .collect();
                self.line(1, &format!("pub fn new({}) -> Self {{", params.join(", ")));
                self.line(2, "Self {");
                for f in &fields {
                    let value = match (&f.default, f.ty.as_str()) {
                        (Some(d), _) => format!("{}: {d}", f.name),
                        (None, "String") => format!("{0}: {0}.into()", f.name),
                        (None, t) if t.starts_with("Box<") => format!("{0}: Box::new({0})", f.name),
                        (None, _) => f.name.clone(),
                    };
                    self.line(3, &format!("{value},"));
                }
                self.line(2, "}");
                self.line(1, "}");
            }
            if split {
                if required {
                    self.out.push('\n');
                }
                self.line(1, "#[inline(never)]");
                self.line(1, "fn read_attributes(r: &mut Reader<'_, '_, '_>, v: &mut Self) -> Result<(), Error> {");
                self.read_attributes(c);
                self.line(2, "Ok(())");
                self.line(1, "}");
                self.out.push('\n');
                self.line(1, "#[inline(never)]");
                self.line(1, "fn write_attributes(&self, w: &mut Writer) -> Result<(), Error> {");
                self.write_attributes(c);
                self.line(2, "Ok(())");
                self.line(1, "}");
            }
            self.line(0, "}");
        }

        self.out.push('\n');
        self.line(0, &format!("impl Content for {name} {{"));
        self.line(1, "fn placeholder() -> Self {");
        let ps: Vec<String> =
            fields.iter().map(|f| if f.placeholder == f.name { f.name.clone() } else { format!("{}: {}", f.name, f.placeholder) }).collect();
        self.line(2, &format!("Self {{ {} }}", ps.join(", ")));
        self.line(1, "}");
        self.out.push('\n');
        let r = if c.fixed.is_empty() && c.attrs.is_empty() && c.body == Body::Empty { "_r" } else { "r" };
        let v = if c.attrs.is_empty() && c.body == Body::Empty { "_v" } else { "v" };
        self.line(1, &format!("fn read_into({r}: &mut Reader<'_, '_, '_>, {v}: &mut Self) -> Result<(), Error> {{"));
        self.read_content(c, split)?;
        self.line(2, "Ok(())");
        self.line(1, "}");
        self.out.push('\n');
        let w = if c.fixed.is_empty() && c.attrs.is_empty() && c.body == Body::Empty { "_w" } else { "w" };
        self.line(1, &format!("fn write(&self, {w}: &mut Writer) -> Result<(), Error> {{"));
        if split {
            self.line(2, "self.write_attributes(w)?;");
        } else {
            self.write_attributes(c);
        }
        self.write_content(c)?;
        self.line(2, "Ok(())");
        self.line(1, "}");
        self.line(0, "}");

        if let Some(root) = root.filter(|r| r.element.starts_with("idPkg:")) {
            self.out.push('\n');
            self.line(0, &format!("impl crate::sealed::Sealed for {name} {{}}"));
            self.out.push('\n');
            self.line(0, &format!("impl PartFile for {name} {{"));
            self.line(1, &format!("const ELEMENT: &'static str = {:?};", root.element));
            self.line(1, &format!("const SCHEMA: &'static str = {:?};", root.file));
            self.out.push('\n');
            self.line(1, "fn from_xml(xml: &str, options: &ReadOptions) -> Result<Parsed<Self>, Error> {");
            self.line(2, "crate::xml::from_xml(xml, options)");
            self.line(1, "}");
            self.out.push('\n');
            self.line(1, "fn to_xml(&self) -> Result<String, Error> {");
            self.line(2, "crate::xml::to_xml(self)");
            self.line(1, "}");
            self.line(0, "}");
        }
        Ok(())
    }

    fn read_attributes(&mut self, c: &Content) {
        for f in &c.fixed {
            self.line(2, &format!("r.fixed({:?}, {:?}, {})?;", f.name, f.value, f.token));
        }
        for a in &c.attrs {
            let call = if a.required { "attr" } else { "opt_attr" };
            self.line(2, &format!("v.{} = r.{call}({:?})?;", a.field, a.name));
        }
    }

    fn write_attributes(&mut self, c: &Content) {
        for f in &c.fixed {
            self.line(2, &format!("w.fixed({:?}, {:?})?;", f.name, f.value));
        }
        for a in &c.attrs {
            let call = if a.required { "attr" } else { "opt_attr" };
            self.line(2, &format!("w.{call}({:?}, &self.{})?;", a.name, a.field));
        }
    }

    fn read_content(&mut self, c: &Content, split: bool) -> Result<(), String> {
        if let Body::Children(items) = &c.body {
            let mut names: Vec<String> = Vec::new();
            for item in items {
                match item {
                    Item::Elem(f) => names.push(f.elem.name.clone()),
                    Item::Interleave(slots) => {
                        for s in slots {
                            match s {
                                Slot::Elem(f) => names.push(f.elem.name.clone()),
                                Slot::Group { ty, .. } => {
                                    if let TypeKind::Children(ms) = &self.model.types[*ty].kind {
                                        names.extend(ms.iter().map(|m| m.elem.name.clone()));
                                    }
                                }
                            }
                        }
                    }
                }
            }
            let list: Vec<String> = names.iter().map(|n| format!("{n:?}")).collect();
            self.line(2, &format!("r.known(&[{}])?;", list.join(", ")));
        }
        if split {
            self.line(2, "Self::read_attributes(r, v)?;");
        } else {
            self.read_attributes(c);
        }
        match &c.body {
            Body::Empty => {}
            Body::Text { field, .. } => self.line(2, &format!("v.{field} = r.text()?;")),
            Body::Children(items) => {
                for item in items {
                    match item {
                        Item::Elem(f) => {
                            let line = self.read_field(f);
                            self.line(2, &line);
                        }
                        Item::Interleave(slots) => self.read_interleave(slots)?,
                    }
                }
            }
        }
        Ok(())
    }

    fn read_interleave(&mut self, slots: &[Slot]) -> Result<(), String> {
        let mut before: Vec<String> = Vec::new();
        let mut arms: Vec<String> = Vec::new();
        let mut after: Vec<String> = Vec::new();
        for s in slots {
            match s {
                Slot::Elem(f) => {
                    let (field, name) = (&f.field, &f.elem.name);
                    if f.boxed {
                        return Err(format!("{name}: recursion through an interleaved element is not supported"));
                    }
                    let arm = match (f.occurs, Self::in_place(&f.elem)) {
                        (Occurs::Many, true) => format!("r.push_into({name:?}, &mut v.{field})?"),
                        (Occurs::Many, false) => format!("v.{field}.push(r.elem({name:?}, {})?)", self.read_fn(&f.elem)),
                        (Occurs::Optional, true) => format!("r.once_into({name:?}, &mut v.{field})?"),
                        (Occurs::Optional, false) => format!("r.once({name:?}, &mut v.{field}, {})?", self.read_fn(&f.elem)),
                        (Occurs::One, true) => {
                            before.push(format!("let mut seen_{field} = false;"));
                            after.push(format!("r.require(seen_{field}, {name:?})?;"));
                            format!("r.once_required_into({name:?}, &mut v.{field}, &mut seen_{field})?")
                        }
                        (Occurs::One, false) => {
                            before.push(format!("let mut {field} = None;"));
                            after.push(format!("v.{field} = r.required({field}, {name:?})?;"));
                            format!("r.once({name:?}, &mut {field}, {})?", self.read_fn(&f.elem))
                        }
                    };
                    arms.push(format!("Some({name:?}) => {arm},"));
                }
                Slot::Group { field, ty } => {
                    let TypeKind::Children(ms) = &self.model.types[*ty].kind else {
                        return Err("group is not a children type".to_owned());
                    };
                    let group = self.name(*ty).to_owned();
                    for m in ms {
                        let name = &m.elem.name;
                        let arm = if m.elem.ty == Ty::Unit && m.elem.fixed.is_empty() {
                            format!("{{ r.elem({name:?}, |_| Ok(()))?; v.{field}.push({group}::{}) }}", m.name)
                        } else if m.boxed && Self::in_place(&m.elem) {
                            format!("v.{field}.push({group}::{}(r.boxed({name:?})?))", m.name)
                        } else {
                            let read = self.read_fn(&m.elem);
                            let read = if m.boxed { format!("|r| ({read})(r).map(Box::new)") } else { read };
                            format!("v.{field}.push({group}::{}(r.elem({name:?}, {read})?))", m.name)
                        };
                        arms.push(format!("Some({name:?}) => {arm},"));
                    }
                }
            }
        }
        for b in before {
            self.line(2, &b);
        }
        self.line(2, "loop {");
        self.line(3, "match r.peek() {");
        for a in arms {
            self.line(4, &a);
        }
        self.line(4, "_ => break,");
        self.line(3, "}");
        self.line(2, "}");
        for a in after {
            self.line(2, &a);
        }
        Ok(())
    }

    fn write_content(&mut self, c: &Content) -> Result<(), String> {
        if let Body::Text { field, .. } = &c.body {
            self.line(2, &format!("w.text(&self.{field})?;"));
        }
        if let Body::Children(items) = &c.body {
            for item in items {
                let slots: Vec<Slot> = match item {
                    Item::Elem(f) => vec![Slot::Elem(f.clone())],
                    Item::Interleave(slots) => slots.clone(),
                };
                for s in slots {
                    match s {
                        Slot::Elem(f) => {
                            let line = self.write_field(&f);
                            self.line(2, &line);
                        }
                        Slot::Group { field, .. } => self.line(2, &format!("for v in &self.{field} {{ v.write(w)?; }}")),
                    }
                }
            }
        }
        Ok(())
    }

    // -- choices -------------------------------------------------------------------

    fn choice(&mut self, name: &str, doc: &[String], vs: &[Variant]) -> Result<(), String> {
        self.doc(0, doc);
        self.line(0, "#[derive(Debug, Clone, PartialEq)]");
        self.line(0, &format!("pub enum {name} {{"));
        for v in vs {
            self.line(1, &format!("/// `{}`.{}", escape_code(&v.schema), since(&v.trace)));
            match &v.ty {
                Ty::Unit => self.line(1, &format!("{},", v.name)),
                ty => self.line(1, &format!("{}({}),", v.name, Self::boxed(self.ty_rust(ty), v.boxed))),
            }
        }
        self.line(0, "}");
        self.out.push('\n');
        self.line(0, &format!("impl Content for {name} {{"));
        self.line(1, "fn placeholder() -> Self {");
        let first = vs.first().ok_or_else(|| format!("{name}: choice without alternatives"))?;
        let placeholder = match &first.ty {
            Ty::Unit => format!("Self::{}", first.name),
            ty => format!(
                "Self::{}({})",
                first.name,
                if first.boxed { format!("Box::new({})", self.ty_placeholder(ty)) } else { self.ty_placeholder(ty) }
            ),
        };
        self.line(2, &placeholder);
        self.line(1, "}");
        self.out.push('\n');
        self.line(1, "fn read_into(r: &mut Reader<'_, '_, '_>, v: &mut Self) -> Result<(), Error> {");
        self.line(2, &format!("*v = r.choice({name:?}, &["));
        for v in vs {
            let mut body: Vec<String> = v.fixed.iter().map(|f| format!("r.fixed({:?}, {:?}, {})?;", f.name, f.value, f.token)).collect();
            let value = match &v.ty {
                Ty::Unit => format!("Self::{}", v.name),
                ty if v.boxed => format!("Self::{}(Box::new({}?))", v.name, self.ty_read(ty)),
                ty => format!("Self::{}({}?)", v.name, self.ty_read(ty)),
            };
            body.push(format!("Ok({value})"));
            let param = if v.fixed.is_empty() && v.ty == Ty::Unit { "_" } else { "r" };
            self.line(3, &format!("|{param}| {{ {} }},", body.join(" ")));
        }
        self.line(2, "])?;");
        self.line(2, "Ok(())");
        self.line(1, "}");
        self.out.push('\n');
        self.line(1, "fn write(&self, w: &mut Writer) -> Result<(), Error> {");
        self.line(2, "match self {");
        for v in vs {
            let mut body: Vec<String> = v.fixed.iter().map(|f| format!("w.fixed({:?}, {:?})?;", f.name, f.value)).collect();
            let pattern = match &v.ty {
                Ty::Unit => {
                    body.push("Ok(())".to_owned());
                    format!("Self::{}", v.name)
                }
                ty => {
                    body.push(self.ty_write(ty, "v", 0));
                    format!("Self::{}(v)", v.name)
                }
            };
            self.line(3, &format!("{pattern} => {{ {} }}", body.join(" ")));
        }
        self.line(2, "}");
        self.line(1, "}");
        self.line(0, "}");
        Ok(())
    }

    // -- interleaved children --------------------------------------------------------

    fn children(&mut self, name: &str, doc: &[String], ms: &[Member]) -> Result<(), String> {
        self.doc(0, doc);
        self.line(0, "#[derive(Debug, Clone, PartialEq)]");
        self.line(0, &format!("pub enum {name} {{"));
        for m in ms {
            self.line(1, &format!("/// `<{}>`.{}", m.elem.name, since(&m.trace)));
            match &m.elem.ty {
                Ty::Unit if m.elem.fixed.is_empty() => self.line(1, &format!("{},", m.name)),
                _ => self.line(1, &format!("{}({}),", m.name, Self::boxed(self.elem_rust(&m.elem), m.boxed))),
            }
        }
        self.line(0, "}");
        self.out.push('\n');
        self.line(0, &format!("impl {name} {{"));
        self.line(1, "fn write(&self, w: &mut Writer) -> Result<(), Error> {");
        self.line(2, "match self {");
        for m in ms {
            if m.elem.ty == Ty::Unit && m.elem.fixed.is_empty() {
                self.line(3, &format!("Self::{} => {},", m.name, self.write_elem(&m.elem, "v", 0)));
            } else {
                self.line(3, &format!("Self::{}(v) => {},", m.name, self.write_elem(&m.elem, "v", 0)));
            }
        }
        self.line(2, "}");
        self.line(1, "}");
        self.line(0, "}");
        Ok(())
    }
}

/// ` Since IDML 7.0.` after a field's description, or nothing.
fn since(trace: &Trace) -> String {
    trace.since.as_ref().map(|s| format!(" {s}")).unwrap_or_default()
}

/// Schema documentation as Markdown text.
fn escape_doc(s: &str) -> String {
    s.replace('\\', "\\\\").replace('[', "\\[").replace(']', "\\]").replace('<', "\\<").replace('>', "\\>")
}

/// Text inside backticks cannot contain a backtick.
fn escape_code(s: &str) -> String {
    s.replace('`', "'")
}
